mkdir -p /app/output && cat > /app/output/styles.css << 'EOF'
:root {
  --bg: #f5f2ed;
  --text: #1a1a1a;
  --muted: #6d675f;
  --line: #d8d1c8;
  --accent-terracotta: #c88562;
  --accent-sage: #9ba58d;
  --accent-sand: #d8c19c;
  --accent-clay: #b27d62;
  --max-width: 1220px;
  --reading-width: 720px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  backdrop-filter: blur(4px);
  border-bottom: 1px solid transparent;
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1.5rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}
.brand {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.nav-desktop {
  display: flex;
  align-items: center;
  gap: 1.8rem;
  font-size: 0.95rem;
}
.nav-desktop a { position: relative; }
.nav-desktop a::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -0.32rem;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width .28s ease;
}
.nav-desktop a:hover::after,
.nav-desktop a[aria-current='page']::after { width: 100%; }

.menu-button {
  display: none;
  border: 0;
  background: transparent;
  width: 2.3rem;
  height: 2.3rem;
  padding: 0;
  cursor: pointer;
  position: relative;
}
.menu-button span {
  position: absolute;
  left: .35rem;
  right: .35rem;
  height: 2px;
  background: var(--text);
  transition: transform .28s ease, opacity .2s ease, top .28s ease;
}
.menu-button span:nth-child(1){ top: .72rem; }
.menu-button span:nth-child(2){ top: 1.13rem; }
.menu-button span:nth-child(3){ top: 1.54rem; }
.menu-button[aria-expanded='true'] span:nth-child(1){ top: 1.13rem; transform: rotate(45deg); }
.menu-button[aria-expanded='true'] span:nth-child(2){ opacity: 0; }
.menu-button[aria-expanded='true'] span:nth-child(3){ top: 1.13rem; transform: rotate(-45deg); }

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 30;
  display: grid;
  place-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity .26s ease;
}
.mobile-overlay.open { opacity: 1; pointer-events: auto; }
.mobile-overlay nav {
  display: grid;
  gap: 1.25rem;
  text-align: center;
}
.mobile-overlay a {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(2rem, 8vw, 3.4rem);
}

main { max-width: var(--max-width); margin: 0 auto; padding: 2rem; }
.section-space { margin-top: clamp(5rem, 11vw, 10rem); }

.hero-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: clamp(1.5rem, 5vw, 5rem);
  align-items: end;
  min-height: 58vh;
}
.kicker {
  letter-spacing: .1em;
  text-transform: uppercase;
  font-size: .72rem;
  color: var(--muted);
  margin-bottom: 1.1rem;
}
.hero-title,
.page-title,
.contact-title {
  font-family: 'Playfair Display', Georgia, serif;
  font-weight: 700;
  line-height: 0.96;
  letter-spacing: -0.02em;
}
.hero-title { font-size: clamp(3rem, 9.2vw, 8.2rem); margin: 0; }
.hero-sub {
  margin-top: 1.4rem;
  max-width: 34ch;
  color: #2c2a28;
  font-size: 1.08rem;
}

.placeholder-stack {
  display: grid;
  gap: 1rem;
  align-self: center;
}
.placeholder {
  border-radius: 2px;
  min-height: 160px;
}
.placeholder:nth-child(1){ background: var(--accent-terracotta); height: 180px; }
.placeholder:nth-child(2){ background: var(--accent-sage); height: 220px; margin-left: 8%; }
.placeholder:nth-child(3){ background: var(--accent-sand); height: 170px; margin-left: 18%; }

.marquee-wrap {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 2rem 0;
}
.marquee-row {
  overflow: hidden;
  white-space: nowrap;
  position: relative;
  margin: 0.7rem 0;
}
.marquee-track {
  display: inline-flex;
  min-width: max-content;
  will-change: transform;
  animation: marquee-left 26s linear infinite;
}
.marquee-row.reverse .marquee-track { animation-name: marquee-right; }
.marquee-item {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.2rem, 2.5vw, 2.05rem);
  margin-right: 2.2rem;
}
@keyframes marquee-left { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes marquee-right { from { transform: translateX(-50%); } to { transform: translateX(0); } }

.editorial {
  max-width: var(--reading-width);
  margin: 0 auto;
}
.editorial .page-title { font-size: clamp(2.4rem, 8vw, 6rem); margin: 0 0 2rem; }
.editorial p {
  font-size: clamp(1.05rem, 1.9vw, 1.28rem);
  line-height: 1.9;
  color: #292724;
  margin: 0 0 1.5rem;
}
.editorial .signature {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.35rem;
  margin-top: 2.4rem;
}

.services-wrap .page-title,
.clients-wrap .page-title {
  font-size: clamp(2.5rem, 7.3vw, 5.6rem);
  margin: 0 0 1rem;
}

.service-list {
  display: grid;
  gap: 2rem;
  margin-top: 2rem;
}
.service-item {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 2rem;
  padding-top: 1.7rem;
  border-top: 1px solid var(--line);
}
.service-item h3 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.6rem, 4vw, 2.6rem);
  margin: 0;
}
.service-item p { margin: 0; color: #2c2a28; font-size: 1.04rem; }

.clients-grid {
  margin-top: 2.2rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.2rem 1.6rem;
}
.client-card {
  border-top: 1px solid var(--line);
  padding-top: 1rem;
}
.client-card h3 {
  margin: 0 0 .5rem;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.35rem, 2vw, 1.85rem);
}
.client-card p { margin: 0; color: #3a3733; }

.contact-wrap {
  min-height: calc(100vh - 110px);
  display: grid;
  align-content: center;
}
.contact-title {
  font-size: clamp(4.5rem, 20vw, 16rem);
  margin: 0;
}
.contact-links {
  margin-top: 2.4rem;
  display: flex;
  gap: 1.4rem;
  flex-wrap: wrap;
  font-size: 1rem;
}
.contact-links a {
  border-bottom: 1px solid var(--text);
  padding-bottom: .12rem;
}

@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; }
  .service-item { grid-template-columns: 1fr; gap: .9rem; }
  .clients-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 760px) {
  .header-inner, main { padding-left: 1.2rem; padding-right: 1.2rem; }
  .nav-desktop { display: none; }
  .menu-button { display: inline-block; }
  .clients-grid { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const menuBtn = document.querySelector('[data-menu-button]');
  const overlay = document.querySelector('[data-mobile-overlay]');

  if (menuBtn && overlay) {
    menuBtn.addEventListener('click', function () {
      const expanded = menuBtn.getAttribute('aria-expanded') === 'true';
      menuBtn.setAttribute('aria-expanded', String(!expanded));
      overlay.classList.toggle('open', !expanded);
      document.body.style.overflow = expanded ? '' : 'hidden';
    });
  }

  const tracks = document.querySelectorAll('.marquee-track');
  tracks.forEach(function (track) {
    const html = track.innerHTML;
    track.innerHTML = html + html;
  });
})();
EOF

